#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(void) {
    char line[10000];
    if (!fgets(line, sizeof(line), stdin)) return 0;
    int a[1000];
    int n = 0;
    char *tok = strtok(line, " \t\r\n");
    while (tok) {
        a[n++] = atoi(tok);
        tok = strtok(NULL, " \t\r\n");
    }
    int k;
    if (scanf("%d", &k) != 1) return 0;
    long long total = 0;
    for (int i = 0; i < n; i++) {
        if (a[i] >= k) {
            total += (long long)(i + 1) * a[i];
        }
    }
    printf("%lld\n", total);
    return 0;
}

