    int k;
    if (!(cin >> k)) return 0;
    long long total = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        if (a[i] >= k) {
            total += (long long)(i + 1) * a[i];
        }
    }
    cout << total << endl;
    return 0;
}

