#include <stdio.h>
#include <stdbool.h>

bool is_prime(int x) {
    if (x < 2) return false;
    for (int d = 2; (long long)d * d <= x; d++) {
        if (x % d == 0) return false;
    }
    return true;
}

int main(void) {
    int k, n;
    if (scanf("%d %d", &k, &n) != 2) return 0;
    long long total = 0;
    int primes_found = 0;
    for (int i = 0; i < n; i++) {
        int fare;
        scanf("%d", &fare);
        total += fare;
        if (primes_found < k && is_prime(fare)) {
            total += fare;
            primes_found++;
        }
    }
    printf("%lld\n", total);
    return 0;
}

