#include <string.h>

int main(void) {
    char s[10000];
    if (scanf("%s", s) == 1) {
        int seen[26] = {0};
        int distinct = 0;
        int len = strlen(s);
        for (int i = 0; i < len; i++) {
            int idx = s[i] - 'a';
            if (!seen[idx]) {
                seen[idx] = 1;
                distinct++;
            }
            int shifted = (idx + distinct) % 26;
            s[i] = (char)('a' + shifted);
        }
        printf("%s\n", s);
    }
    return 0;
}

