        int distinct = 0;
        for (char &c : s) {
            int idx = c - 'a';
            if (!seen[idx]) {
                seen[idx] = true;
                distinct++;
            }
            c = (char)('a' + (idx + distinct) % 26);
        }
        cout << s << endl;
    }
    return 0;
}

