int main(void) {
    int n;
    if (scanf("%d", &n) != 1 || n <= 1) {
        printf("0\n");
        return 0;
    }
    int prev;
    scanf("%d", &prev);
    long long total = 0;
    for (int i = 1; i < n; i++) {
        int curr;
        scanf("%d", &curr);
        if (prev > curr) {
            total += prev + curr;
        }
        prev = curr;
    }
    printf("%lld\n", total);
    return 0;
}

