#include <stdio.h>

int count_distinct_prime_factors(int n) {
    if (n <= 1) return 0;
    int cnt = 0;
    int temp = n;
    for (int d = 2; (long long)d * d <= temp; d++) {
        if (temp % d == 0) {
            cnt++;
            while (temp % d == 0) {
                temp /= d;
            }
        }
    }
    if (temp > 1) cnt++;
    return cnt;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    long long total = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        total += (long long)x * count_distinct_prime_factors(x);
    }
    printf("%lld\n", total);
    return 0;
}

