    if (scanf("%d", &d) != 1) return 0;
    char line[10000];
    while (getchar() != '\n');
    if (!fgets(line, sizeof(line), stdin)) {
        printf("0\n");
        return 0;
    }
    char *tok = strtok(line, " \t\r\n");
    if (!tok) {
        printf("0\n");
        return 0;
    }
    int prev = atoi(tok);
    int boosts = 0;
    tok = strtok(NULL, " \t\r\n");
    while (tok) {
        int curr = atoi(tok);
        if (curr - prev > d) {
            boosts++;
        }
        prev = curr;
        tok = strtok(NULL, " \t\r\n");
    }
    printf("%d\n", boosts);
    return 0;
}

