    string line;
    while (line.empty()) {
        if (!getline(cin, line)) {
            cout << 0 << endl;
            return 0;
        }
    }
    stringstream ss(line);
    vector<int> s;
    int val;
    while (ss >> val) s.push_back(val);
    int n = 0;
    cin >> n;
    if (k <= 0 || n == 0 || s.empty()) {
        cout << 0 << endl;
        return 0;
    }
    int rem = k, last_row = 0;
    for (int i = 0; i < (int)s.size() && i < n; ++i) {
        if (rem > 0) {
            last_row = i + 1;
            rem -= s[i];
        } else {
            break;
        }
    }
    cout << last_row << endl;
    return 0;
}

