#include <stdio.h>
#include <stdlib.h>

int cmp_desc(const void *a, const void *b) {
    return (*(int *)b - *(int *)a);
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int r[10000];
    for (int i = 0; i < n; i++) scanf("%d", &r[i]);
    int t;
    scanf("%d", &t);
    qsort(r, n, sizeof(int), cmp_desc);
    int rank = 0;
    for (int i = 0; i < n; i++) {
        if (r[i] == t) {
            rank = i + 1;
            break;
        }
    }
    printf("%d\n", rank);
    return 0;
}

