int main(void) {
    int n;
    char t[10000];
    if (scanf("%d %s", &n, t) == 2) {
        if (n <= 0 || t[0] == '\0') {
            printf("0\n");
            return 0;
        }
        int count = 1;
        for (int i = 1; i < n && t[i] != '\0'; i++) {
            if (t[i] != t[i-1]) {
                count++;
            }
        }
        printf("%d\n", count);
    }
    return 0;
}

